def seasonal(history, period, horizon):
    cycle = history[-period:]
    return [cycle[i % period] for i in range(horizon)]

def folds(n, minimum, horizon):
    return [(cut, cut, cut + horizon)
            for cut in range(minimum, n-horizon+1, horizon)]

def wape(actual, predicted):
    total = sum(abs(y) for y in actual)
    return sum(abs(y-p) for y,p in zip(actual,predicted)) / total if total else None

def interval_coverage(actual, low, high):
    if not actual:
        return None
    return sum(a <= y <= b for y,a,b in zip(actual, low, high)) / len(actual)

def recommend(candidates, seen, k):
    blocked = set(seen)
    result = []
    for item in candidates:
        if len(result) >= k:
            break
        if item not in blocked:
            result.append(item)
            blocked.add(item)
    return result

def recall_at_k(ranking, relevant, k):
    targets = set(relevant)
    return len(set(ranking[:k]) & targets) / len(targets) if targets else None

def catalog_coverage(rankings, catalog):
    allowed = set(catalog)
    shown = {item for row in rankings for item in row}
    return len(shown & allowed) / len(allowed) if allowed else None
